/* Green Control components. Needs the green-control-theme variables (gc-*) or the prototype's own names. */
:root {
  --bg-page: var(--gc-bg-page);
  --bg-surface: var(--gc-bg-surface);
  --bg-raised: var(--gc-bg-raised);
  --bg-chip: var(--gc-bg-chip);
  --line: var(--gc-line);
  --text: var(--gc-text);
  --muted: var(--gc-muted);
  --accent: var(--gc-accent);
  --on-accent: var(--gc-on-accent);
  --glass: var(--gc-glass);
  --glass-raised: var(--gc-glass-raised);
  --sheen: var(--gc-sheen);
  --edge-hi: var(--gc-edge-hi);
  --drop: var(--gc-drop);
  --link: var(--gc-link);
  --cta-bg: var(--gc-cta-bg);
  --cta-fg: var(--gc-cta-fg);
  --sel-bg: var(--gc-sel-bg);
  --sel-fg: var(--gc-sel-fg);
  --dot: var(--gc-dot);
  --pool: var(--gc-pool);
  --badge-bg: var(--gc-badge-bg);
  --font-mono: "DM Mono", ui-monospace, monospace;
  --ease: var(--gc-ease, cubic-bezier(0.2, 0, 0, 1));
  --spring: var(--gc-spring, cubic-bezier(0.34, 1.56, 0.64, 1));
}
.glass { background: linear-gradient(var(--sheen), transparent 60%), var(--glass); -webkit-backdrop-filter: blur(24px); backdrop-filter: blur(24px); box-shadow: inset 0 1px 0 var(--edge-hi), var(--drop); }
.block { background: linear-gradient(var(--sheen), transparent 60%), var(--glass-raised); box-shadow: inset 0 1px 0 var(--edge-hi); }
.spark { width: 14px; height: 14px; flex: none; }
.spark circle { fill: var(--text); }
.spark circle.o { fill: var(--accent); }

.state { display: inline-flex; align-items: center; gap: 6px; color: var(--muted); }
.state i { width: 7px; height: 7px; background: currentColor; display: block; }
.state.issue { color: var(--accent); }
.link { display: inline-flex; align-items: center; gap: 6px; color: var(--link); text-decoration: underline; text-underline-offset: 3px; text-decoration-thickness: 1px; }
.link .g { width: 6px; height: 6px; border-radius: 99px; background: var(--link); flex: none; }

.card { padding: 16px; display: grid; gap: 10px; }
.card-head { display: flex; align-items: center; gap: 10px; }
.card-foot { display: flex; justify-content: flex-end; }
.chips { display: flex; flex-wrap: wrap; gap: 6px; }
.echip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px 0 5px; background: var(--bg-raised); font-size: 13px; }
.echip .num { width: 16px; height: 16px; line-height: 1; display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; background: var(--badge-bg); color: var(--on-accent); }
.ev { padding: 14px; display: grid; gap: 8px; }
.ev-top { display: flex; align-items: baseline; gap: 8px; }
.bar { position: relative; height: 8px; }
.bar i { position: absolute; top: 2px; height: 4px; display: block; }
.bar .tr { left: 0; right: 0; background: var(--line); }
.bar .now { left: 0; background: var(--accent); }
.bar .tk { top: 0; width: 2px; height: 8px; background: var(--muted); }

.proc { display: flex; align-items: center; gap: 10px; font-size: 13px; line-height: 19px; }
.ring { width: 10px; height: 10px; border-radius: 99px; border: 1.5px solid var(--line); border-top-color: var(--accent); animation: spin 700ms linear infinite; flex: none; }
@keyframes spin { to { transform: rotate(360deg); } }
.tick { width: 12px; height: 12px; flex: none; color: var(--muted); }
.tick path { fill: none; stroke: currentColor; stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }

.conf { display: grid; gap: 6px; }
.conf-bar { display: flex; gap: 2px; height: 8px; }
.conf-bar i { flex: 1; background: var(--line); }
.conf-bar i.on { background: var(--text); }
.conf-bar i.hot { background: var(--accent); }

.pl { display: grid; }
.pl-item { position: relative; display: grid; grid-template-columns: 18px 1fr; column-gap: 12px; padding-bottom: 16px; }
.pl-item:last-child { padding-bottom: 0; }
.pl-item:not(:last-child)::before { content: ""; position: absolute; left: 8.5px; top: 9px; bottom: -9px; width: 1px; background: var(--line); }
.pl-dot { position: relative; z-index: 1; width: 18px; height: 18px; display: grid; place-items: center; background: var(--bg-page); }
.pl-dot .num { width: 16px; height: 16px; line-height: 1; display: grid; place-items: center; font-family: var(--font-mono); font-size: 10px; box-shadow: inset 0 0 0 1px var(--muted); color: var(--muted); }
.pl-item.on .num { background: var(--accent); color: var(--on-accent); box-shadow: none; }
.pl-item.on .when { color: var(--accent); }
.pl-body { display: grid; gap: 4px; justify-items: start; }
.pl-act { display: flex; align-items: center; gap: 10px; margin-top: 8px; flex-wrap: wrap; }
.draft { display: inline-flex; padding: 1px 6px; box-shadow: inset 0 0 0 1px var(--accent); color: var(--accent); }

.toast { display: flex; align-items: center; gap: 12px; padding: 9px 14px 9px 12px; font-size: 13px; width: max-content; max-width: 100%; }
.toast .div { width: 1px; height: 14px; background: var(--line); }
.toast svg { width: 14px; height: 14px; stroke: var(--text); fill: none; stroke-width: 1.5; stroke-linecap: round; stroke-linejoin: round; flex: none; }
.toast-float { position: absolute; left: 50%; top: 64px; transform: translateX(-50%); z-index: 2; animation: toastIn 520ms var(--spring) both; }
@keyframes toastIn { from { opacity: 0; transform: translate(-50%, -12px); } }

.acrow { position: relative; display: grid; grid-template-columns: 1fr auto; gap: 4px 12px; padding: 12px 14px; box-shadow: inset 0 0 0 1px var(--line); }
.acrow .track { grid-column: 1 / -1; position: relative; height: 8px; margin-top: 6px; }
.acrow .track i { position: absolute; display: block; }
.acrow .base { left: 0; right: 0; top: 4px; height: 1px; background: var(--line); }
.acrow .run { top: 2px; height: 5px; left: 12%; width: 46%; background: var(--accent); }
.acrow .plan { top: 1px; width: 6px; height: 6px; left: 78%; box-shadow: inset 0 0 0 1.5px var(--accent); }
.acrow .now { top: -4px; width: 1px; height: 16px; left: 52%; background: var(--accent); }


/* ---------- v1.1: buttons, segmented control, logo (gaps found by the agent test) ---------- */
/* Buttons are square. One primary (.cta) per view. Secondary is .pbtn. There is no pill button. */
.cta { display: inline-flex; align-items: center; gap: 8px; height: 34px; padding: 0 14px; background: var(--cta-bg); color: var(--cta-fg); font-weight: 500; font-size: 14px; border: 0; border-radius: 0; cursor: pointer; transition: transform 140ms var(--ease), filter 200ms; }
.cta:hover { filter: brightness(1.08); }
.cta:active { transform: scale(0.96); }
.pbtn { display: inline-flex; align-items: center; height: 32px; padding: 0 12px; background: transparent; color: var(--text); border: 0; border-radius: 0; box-shadow: inset 0 0 0 1px var(--line); font-size: 13px; cursor: pointer; }
.pbtn.primary { background: var(--cta-bg); color: var(--cta-fg); box-shadow: none; }
.pbtn:disabled { opacity: 0.45; cursor: not-allowed; }
/* Segmented control: <div class="seg" role="group"><button aria-pressed="true">Night</button><button aria-pressed="false">Day</button></div> */
.seg { display: inline-flex; padding: 2px; gap: 2px; background: var(--bg-surface); box-shadow: inset 0 0 0 1px var(--line); }
.seg button { padding: 4px 10px; font-size: 13px; color: var(--muted); background: none; border: 0; border-radius: 0; cursor: pointer; }
.seg button[aria-pressed="true"] { background: var(--sel-bg); color: var(--sel-fg); }
/* Spark (the AI signal, only where the AI speaks or acts):
   <svg class="spark" viewBox="0 0 14 14"><circle cx="7" cy="2.3" r="1.5"/><circle cx="2.3" cy="7" r="1.5"/><circle class="o" cx="7" cy="7" r="1.5"/><circle cx="11.7" cy="7" r="1.5"/><circle cx="7" cy="11.7" r="1.5"/></svg> */
/* Logo (the product, top-left only; never use the spark as the logo): a 5x5 dot "G", one accent dot.
   <svg class="logo" viewBox="0 0 28 28"> rows ".XXX." "X...." "X.OXX" "X...X" ".XXX." ; cx = 5.2 + col*4.4, cy = 5.2 + row*4.4, r = 1.7 ; X = text, O = accent </svg> */
.logo { width: 24px; height: 24px; flex: none; }
.logo circle { fill: var(--text); }
.logo circle.o { fill: var(--accent); }

/* ---------- v1.3: owner row (who acts on the plan) ---------- */
/* <div class="owner"><span class="t-label muted">Owner</span><a class="link"><span class="g"></span>Energy desk</a><span class="muted">on shift</span><a class="link"><span class="g"></span>Chen Yu</a><button class="pbtn">Assign</button></div>
   The AI suggests the owner; a person taps Assign. Assign is undoable like any applied step. */
.owner { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; font-size: 13px; }
.owner .pbtn { margin-left: auto; }

/* ---------- v1.5: keyboard focus (found by gc-check) ---------- */
/* Every clickable part shows where the keyboard is. Same ring everywhere: 1.5px in the text colour, 2px out. */
:where(.cta, .pbtn, .seg button, .link, .echip, button, a[href], [role="button"]):focus-visible { outline: 1.5px solid var(--text); outline-offset: 2px; }

import { cn } from "@/lib/utils"

/** Green Control spinner: a square-cornered ring that inherits the text colour. */
export function Spinner({ className }: { className?: string }) {
  return (
    <span
      aria-hidden="true"
      className={cn(
        "inline-block size-3 shrink-0 animate-spin rounded-full border-[1.5px] border-current/30 border-t-current motion-reduce:animate-none",
        className
      )}
    />
  )
}

import * as React from "react"
import { cva, type VariantProps } from "class-variance-authority"
import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * Green Control button.
 * Square. One `primary` per view: the person's next decision (Investigate, Apply, Assign).
 * States: hover, focus-visible, active (press), disabled, loading.
 * When `loading`, the label should say what is happening ("Applying…").
 */
const buttonVariants = cva(
  "inline-flex shrink-0 cursor-pointer items-center justify-center gap-2 whitespace-nowrap rounded-none font-medium outline-none transition-[background-color,transform,opacity] duration-[260ms] ease-spring active:duration-75 active:ease-out focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground active:scale-[0.97] disabled:cursor-not-allowed disabled:opacity-40 disabled:active:scale-100 motion-reduce:transition-none",
  {
    variants: {
      variant: {
        primary: "bg-primary text-primary-foreground hover:bg-primary/80 active:bg-primary/65",
        secondary: "bg-transparent text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-secondary active:bg-secondary",
        ghost: "bg-transparent text-muted-foreground hover:bg-secondary hover:text-foreground",
      },
      size: {
        default: "h-9 px-3.5 text-sm",
        sm: "h-8 px-3 text-[13px]",
      },
    },
    defaultVariants: { variant: "primary", size: "default" },
  }
)

export interface ButtonProps
  extends React.ButtonHTMLAttributes<HTMLButtonElement>,
    VariantProps<typeof buttonVariants> {
  /** Sent and waiting. Locks the button and shows a spinner. */
  loading?: boolean
}

export function Button({ className, variant, size, loading = false, disabled, children, ...props }: ButtonProps) {
  return (
    <button
      data-slot="button"
      aria-busy={loading || undefined}
      disabled={disabled || loading}
      className={cn(buttonVariants({ variant, size }), loading && "cursor-progress disabled:opacity-100", className)}
      {...props}
    >
      {loading && <Spinner />}
      {children}
    </button>
  )
}

export { buttonVariants }

import { cn } from "@/lib/utils"

/**
 * What state an object is in: a glyph and a word. All glyphs share one 10px box.
 * square = neutral (watching, investigating) · triangle = a problem · diamond = a chance to save · tick = done.
 * Only `issue` and `opportunity` use the signal colour. Never the glyph alone.
 */
type State = "watching" | "issue" | "opportunity" | "investigating" | "resolved"

const LABEL: Record<State, string> = { watching: "Watching", issue: "Issue", opportunity: "Opportunity", investigating: "Investigating", resolved: "Resolved" }

const TEXT: Record<State, string> = {
  watching: "text-muted-foreground",
  issue: "text-signal",
  opportunity: "text-foreground",
  investigating: "text-foreground",
  resolved: "text-muted-foreground",
}

function Glyph({ state }: { state: State }) {
  const common = "size-2.5 shrink-0"
  if (state === "issue") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-current")}><path d="M5 1.2 9.4 8.8H.6z" /></svg>
  if (state === "opportunity") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-signal")}><path d="M5 .8 9.2 5 5 9.2.8 5z" /></svg>
  if (state === "resolved") return <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-none stroke-current stroke-[1.6]")}><path d="M1.5 5.2 4 7.5 8.5 2.5" /></svg>
  return (
    <svg viewBox="0 0 10 10" aria-hidden="true" className={cn(common, "fill-current", state === "investigating" && "animate-pulse motion-reduce:animate-none")}>
      <rect x="2" y="2" width="6" height="6" />
    </svg>
  )
}

export interface StateTagProps {
  state?: State
  /** Overrides the default word, e.g. "+14% power". */
  children?: React.ReactNode
  className?: string
}

export function StateTag({ state = "watching", children, className }: StateTagProps) {
  return (
    <span data-slot="state-tag" data-state={state} className={cn("inline-flex items-center gap-1.5 text-[13px] leading-[19px]", TEXT[state], className)}>
      <Glyph state={state} />
      {children ?? LABEL[state]}
    </span>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Whenever the AI names a machine, a team or a work order, it is an object link:
 * a dot and an underlined name that opens exactly that thing.
 * `missing`: the object was removed; the name stays readable, struck through.
 */
export interface ObjectLinkProps extends React.AnchorHTMLAttributes<HTMLAnchorElement> {
  missing?: boolean
}

export function ObjectLink({ missing = false, className, children, ...props }: ObjectLinkProps) {
  return (
    <a
      data-slot="object-link"
      aria-disabled={missing || undefined}
      className={cn(
        "inline-flex cursor-pointer items-center gap-1.5 text-link underline decoration-1 underline-offset-[3px] outline-none transition-[text-decoration-thickness,background-color] duration-150 hover:bg-link/8 hover:decoration-2 focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground",
        "before:size-1.5 before:shrink-0 before:rounded-full before:bg-current before:content-[''] before:transition-transform before:duration-[260ms] before:ease-spring hover:before:scale-[1.4]",
        missing && "pointer-events-none cursor-default text-muted-foreground line-through before:bg-transparent before:shadow-[inset_0_0_0_1px_currentColor]",
        className
      )}
      {...props}
    >
      {children}
    </a>
  )
}

import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * One chip per source the AI checked, numbered in the order it checked them.
 * The same number marks the spot on the drawing and heads the evidence card.
 */
export interface EvidenceChipProps {
  n: number
  label: string
  /** checking: being read · landed: done · stale: older than 15 min */
  status?: "checking" | "landed" | "stale"
  /** Its card is open below. */
  selected?: boolean
  /** Its card or drawing mark is hovered elsewhere. */
  linked?: boolean
  age?: string
  className?: string
}

export function EvidenceChip({ n, label, status = "landed", selected = false, linked = false, age = "15 min", className }: EvidenceChipProps) {
  return (
    <span
      data-slot="evidence-chip"
      data-status={status}
      aria-busy={status === "checking" || undefined}
      className={cn(
        "inline-flex h-7 items-center gap-1.5 bg-raised pr-2 pl-[5px] text-[13px] transition-[box-shadow,background-color] duration-200 hover:shadow-[0_0_0_1.5px_var(--gc-accent)]",
        linked && "shadow-[0_0_0_1.5px_var(--gc-accent)]",
        selected && "bg-foreground text-background",
        status === "checking" && "text-muted-foreground",
        status === "stale" && "opacity-60",
        className
      )}
    >
      {status === "checking" ? (
        <Spinner className="mx-0.5" />
      ) : (
        <span className={cn("grid size-4 place-items-center font-mono text-[10px]", selected ? "bg-background text-foreground" : "bg-[var(--gc-badge-bg)] text-on-signal")}>{n}</span>
      )}
      {label}
      {status === "stale" && <span className="ml-1 font-mono text-xs text-muted-foreground">{age}</span>}
    </span>
  )
}

import { cn } from "@/lib/utils"

/**
 * Twenty square segments and a number. The band decides what the AI may do:
 * 80+ plan · 50–79 draft · below 50 check only (segments turn to the signal colour).
 */
export const CONFIDENCE_ACT = 80
export const CONFIDENCE_REVIEW = 50

export function confidenceBand(value: number) {
  return value >= CONFIDENCE_ACT ? "plan" : value >= CONFIDENCE_REVIEW ? "draft" : "check"
}

export interface ConfidenceMeterProps {
  value: number
  /** A new reading is coming in. */
  updating?: boolean
  className?: string
}

export function ConfidenceMeter({ value, updating = false, className }: ConfidenceMeterProps) {
  const on = Math.round((value / 100) * 20)
  const low = value < CONFIDENCE_REVIEW
  return (
    <div data-slot="confidence-meter" data-band={confidenceBand(value)} className={cn("grid w-full min-w-[220px] gap-1.5", className)}>
      <div className="flex items-baseline justify-between">
        <span className="font-mono text-[11px] uppercase tracking-[0.05em] text-muted-foreground">Confidence</span>
        <span className="font-mono text-xs">{value}%</span>
      </div>
      <div className="flex h-2 gap-0.5" role="meter" aria-valuenow={value} aria-valuemin={0} aria-valuemax={100} aria-label="AI confidence">
        {Array.from({ length: 20 }, (_, i) => (
          <i
            key={i}
            className={cn("flex-1", i < on ? (low ? "bg-signal" : "bg-foreground") : "bg-border", updating && "animate-pulse motion-reduce:animate-none")}
            style={updating ? { animationDelay: `${(i % 4) * 120}ms` } : undefined}
          />
        ))}
      </div>
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * Where a person asks the AI about the object on screen.
 * The placeholder names that object, so the question has a context.
 * States: empty · hover · focus · filled (send on) · sending · error (keeps the text).
 */
export interface AskInputProps {
  object: string
  sending?: boolean
  error?: string
  defaultValue?: string
  onSend?: (text: string) => void
  className?: string
}

export function AskInput({ object, sending = false, error, defaultValue = "", onSend, className }: AskInputProps) {
  const [value, setValue] = React.useState(defaultValue)
  const canSend = value.trim().length > 0 && !sending
  return (
    <div className={cn("grid w-full max-w-[340px] gap-1.5", className)}>
      <form
        data-slot="ask-input"
        onSubmit={(e) => { e.preventDefault(); if (canSend) onSend?.(value) }}
        className={cn(
          "flex h-11 items-center gap-2 bg-background pr-[5px] pl-3.5 shadow-[inset_0_0_0_1px_var(--border)] transition-shadow duration-200 hover:shadow-[inset_0_0_0_1px_var(--muted-foreground)] focus-within:shadow-[inset_0_0_0_1.5px_var(--foreground)]",
          error && "shadow-[inset_0_0_0_1.5px_var(--gc-accent)] hover:shadow-[inset_0_0_0_1.5px_var(--gc-accent)]",
          sending && "opacity-70"
        )}
      >
        <input
          value={value}
          onChange={(e) => setValue(e.target.value)}
          disabled={sending}
          placeholder={`Ask about ${object}…`}
          aria-label={`Ask Green Control about ${object}`}
          aria-invalid={!!error || undefined}
          className="h-full min-w-0 flex-1 bg-transparent text-sm outline-none placeholder:text-muted-foreground"
        />
        <button
          type="submit"
          disabled={!canSend}
          aria-label="Send"
          className="grid size-[34px] cursor-pointer place-items-center bg-primary text-primary-foreground outline-none transition-colors focus-visible:outline-[1.5px] focus-visible:outline-offset-2 focus-visible:outline-foreground disabled:cursor-not-allowed disabled:bg-secondary disabled:text-muted-foreground"
        >
          {sending ? <Spinner /> : <svg viewBox="0 0 14 14" className="size-3.5 fill-none stroke-current stroke-[1.6]"><path d="M2.5 7h9M7.5 3l4 4-4 4" /></svg>}
        </button>
      </form>
      {error && <span role="alert" className="text-[13px] text-signal">{error}</span>}
    </div>
  )
}

import * as React from "react"
import { cn } from "@/lib/utils"

/**
 * Two to four options of the same thing (Night / Day, 7d / 30d). One is always on.
 * The selection slides to the new option instead of jumping, so the eye follows the change.
 */
export interface SegmentedOption<T extends string> {
  value: T
  label: string
  disabled?: boolean
}

export interface SegmentedControlProps<T extends string> {
  options: SegmentedOption<T>[]
  value: T
  onChange: (value: T) => void
  /** Read out by screen readers, e.g. "Theme". */
  label?: string
  className?: string
}

export function SegmentedControl<T extends string>({ options, value, onChange, label, className }: SegmentedControlProps<T>) {
  const refs = React.useRef<Record<string, HTMLButtonElement | null>>({})
  const [box, setBox] = React.useState<{ x: number; w: number } | null>(null)
  const first = React.useRef(true)

  React.useLayoutEffect(() => {
    const place = () => {
      const el = refs.current[value]
      if (el) setBox({ x: el.offsetLeft, w: el.offsetWidth })
    }
    place()
    window.addEventListener("resize", place)
    return () => window.removeEventListener("resize", place)
  }, [value, options])

  React.useEffect(() => {
    first.current = false
  }, [])

  return (
    <div data-slot="segmented" role="group" aria-label={label} className={cn("relative isolate inline-flex p-0.5 shadow-[inset_0_0_0_1px_var(--border)]", className)}>
      {box && (
        <span
          aria-hidden="true"
          className={cn("absolute inset-y-0.5 left-0 -z-10 bg-[var(--gc-sel-bg)] motion-safe:transition-[transform,width] motion-safe:duration-300 motion-safe:ease-gc", first.current && "transition-none")}
          style={{ width: box.w, transform: `translateX(${box.x}px)` }}
        />
      )}
      {options.map((o) => (
        <button
          key={o.value}
          ref={(el) => {
            refs.current[o.value] = el
          }}
          type="button"
          aria-pressed={o.value === value}
          disabled={o.disabled}
          onClick={() => onChange(o.value)}
          className={cn(
            "h-7 px-3 text-[13px] text-muted-foreground outline-none transition-colors duration-200 ease-gc hover:text-foreground",
            "focus-visible:outline-[1.5px] focus-visible:-outline-offset-2 focus-visible:outline-foreground",
