import * as React from "react"
import { cn } from "@/lib/utils"
import { Spinner } from "@/components/ui/spinner"

/**
 * Shown after anything the AI applied. Stays 6 s, pauses while hovered, and always offers Undo.
 */
export interface UndoToastProps {
  message: string
  onUndo: () => Promise<void> | void
  onClose?: () => void
  /** How long it stays, in ms. */
  duration?: number
  className?: string
}

export function UndoToast({ message, onUndo, onClose, duration = 6000, className }: UndoToastProps) {
  const [state, setState] = React.useState<"running" | "paused" | "undoing" | "undone">("running")
  const left = React.useRef(duration)
  const started = React.useRef(Date.now())

  React.useEffect(() => {
    if (state !== "running") return
    started.current = Date.now()
    const t = setTimeout(() => onClose?.(), left.current)
    return () => {
      clearTimeout(t)
      left.current -= Date.now() - started.current
    }
  }, [state, onClose])

  React.useEffect(() => {
    if (state !== "undone") return
    const t = setTimeout(() => onClose?.(), 2000)
    return () => clearTimeout(t)
  }, [state, onClose])

  async function undo() {
    setState("undoing")
    await onUndo()
    setState("undone")
  }

  return (
    <div
      data-slot="toast"
      role="status"
      onMouseEnter={() => state === "running" && setState("paused")}
      onMouseLeave={() => state === "paused" && setState("running")}
      className={cn(
        "relative inline-flex h-10 items-center gap-2.5 overflow-hidden bg-[var(--gc-glass)] px-3.5 text-sm shadow-[inset_0_1px_0_var(--gc-edge-hi),var(--gc-drop)] backdrop-blur-[24px]",
        className
      )}
    >
      {state === "undoing" ? <Spinner /> : (
        <svg viewBox="0 0 14 14" className="size-3.5 fill-none stroke-current stroke-[1.5]" aria-hidden="true"><path d={state === "undone" ? "M4 4h6v6M10 4 4 10" : "M2.5 7.3 5.5 10 11.5 4"} /></svg>
      )}
      <span>{state === "undoing" ? "Undoing…" : state === "undone" ? "Undone" : message}</span>
      {(state === "running" || state === "paused") && (
        <>
          <span className="h-4 w-px bg-border" />
          <button type="button" onClick={undo} className="text-muted-foreground underline underline-offset-[3px] hover:text-foreground">Undo</button>
          <i
            className="absolute bottom-0 left-0 h-px w-full origin-left bg-foreground/40"
            style={{ animation: `gc-toast ${duration}ms linear forwards`, animationPlayState: state === "paused" ? "paused" : "running" }}
          />
          <style>{"@keyframes gc-toast{from{transform:scaleX(1)}to{transform:scaleX(0)}}"}</style>
        </>
      )}
    </div>
  )
}

