/**
 * One action in a plan, with its live status and a thin progress bar.
 * `failed` always says why, in the signal colour.
 */
export type ActionStatus = "planned" | "running" | "done" | "undone" | "failed"

export interface ActionRowProps {
  label: string
  status: ActionStatus
  /** 0–100, used while running. */
  progress?: number
  /** Time shown for planned, done and undone, e.g. "Sat 08:00". */
  time?: string
  /** Required when failed. */
  reason?: string
  className?: string
}

export function ActionRow({ label, status, progress = 0, time, reason, className }: ActionRowProps) {
  const p = status === "done" ? 100 : status === "running" ? progress : status === "failed" ? Math.max(progress, 25) : 0
  const right = status === "running" ? `${progress}%` : status === "failed" ? "Needs you" : status === "done" ? `Done ${time ?? ""}` : status === "undone" ? "Undone" : time
  return (
    <div data-slot="action-row" data-status={status} className={cn("grid grid-cols-[minmax(0,1fr)_auto] items-center gap-x-3 gap-y-2 p-3 shadow-[inset_0_0_0_1px_var(--border)]", className)}>
      <span className={cn("truncate text-[13px]", status === "undone" && "text-muted-foreground line-through")}>{label}</span>
      <span className={cn("whitespace-nowrap font-mono text-xs text-muted-foreground", status === "failed" && "text-signal")}>{right}</span>
      {status !== "planned" && status !== "undone" && (
        <span className="col-span-2 h-1 bg-border">
          <i className={cn("block h-full transition-[width] duration-300 ease-gc", status === "running" ? "bg-signal" : "bg-muted-foreground")} style={{ width: `${p}%` }} />
        </span>
      )}
      {status === "failed" && reason && <span className="col-span-2 text-[13px] text-signal">{reason}</span>}
    </div>
  )
}

